<?php require_once __DIR__.'/../includes/bootstrap.php';require_role(['admin','librarian']);verify_csrf();$id=(int)($_POST['id']??0);$title=trim($_POST['title']??'');$author=trim($_POST['author']??'');$isbn=trim($_POST['isbn']??'')?:null;$publisher=trim($_POST['publisher']??'')?:null;$year=($_POST['published_year']??'')!==''?(int)$_POST['published_year']:null;$cat=($_POST['category_id']??'')!==''?(int)$_POST['category_id']:null;$total=max(0,(int)($_POST['total_copies']??0));$desc=trim($_POST['description']??'')?:null;if(!$title||!$author){flash('error','Title and author are required.');redirect('book_form.php'.($id?'?id='.$id:''));}try{if($id){$s=$conn->prepare('SELECT total_copies,available_copies FROM books WHERE id=? AND is_archived=0');$s->bind_param('i',$id);$s->execute();$old=$s->get_result()->fetch_assoc();if(!$old)throw new Exception('Book not found.');$out=(int)$old['total_copies']-(int)$old['available_copies'];if($total<$out)throw new Exception('Total copies cannot be below the number currently borrowed.');$avail=$total-$out;$s=$conn->prepare('UPDATE books SET title=?,author=?,isbn=?,publisher=?,published_year=?,category_id=?,total_copies=?,available_copies=?,description=? WHERE id=?');$s->bind_param('ssssiiiisi',$title,$author,$isbn,$publisher,$year,$cat,$total,$avail,$desc,$id);$s->execute();log_activity($conn,(int)current_user()['id'],'book_updated',$title);flash('success','Book updated.');}else{$avail=$total;$s=$conn->prepare('INSERT INTO books(title,author,isbn,publisher,published_year,category_id,total_copies,available_copies,description) VALUES(?,?,?,?,?,?,?,?,?)');$s->bind_param('ssssiiiis',$title,$author,$isbn,$publisher,$year,$cat,$total,$avail,$desc);$s->execute();log_activity($conn,(int)current_user()['id'],'book_created',$title);flash('success','Book added.');}}catch(Throwable $e){flash('error','Could not save book. Check duplicate ISBN and input values.');redirect('books.php');}redirect('books.php');?>